/* @autogenerated */
package net.civeira.phylax.features.oauth.authentication.infrastructure.event;

import jakarta.enterprise.context.ApplicationScoped;
import jakarta.enterprise.event.Event;
import lombok.RequiredArgsConstructor;
import net.civeira.phylax.features.oauth.authentication.domain.AuthenticationData;
import net.civeira.phylax.features.oauth.authentication.domain.AuthenticationMode;
import net.civeira.phylax.features.oauth.authentication.domain.AuthenticationResult;
import net.civeira.phylax.features.oauth.authentication.domain.event.LoginFailedEvent;
import net.civeira.phylax.features.oauth.authentication.domain.event.LoginSucceededEvent;
import net.civeira.phylax.features.oauth.authentication.domain.event.OidcEvent;
import net.civeira.phylax.features.oauth.authentication.domain.exception.AuthenticationException;

@ApplicationScoped
@RequiredArgsConstructor
public class OidcEventDispatcher {

  private final Event<OidcEvent> emitter;

  public void dispatch(final AuthenticationResult result) {
    if (result.isRight()) {
      AuthenticationData data = result.getData();
      emitter.fire(LoginSucceededEvent.builder().tenant(data.getTenant())
          .username(data.getUsername()).mode(data.getMode()).time(data.getTime()).build());
    } else {
      AuthenticationException fail = result.getFail();
      emitter.fire(LoginFailedEvent.builder().tenant(fail.getTenant()).username(fail.getUsername())
          .reason(fail.getMessage()).build());
    }
  }

  public void dispatchSuccess(final AuthenticationData data, final AuthenticationMode mode) {
    emitter.fire(LoginSucceededEvent.builder().tenant(data.getTenant()).username(data.getUsername())
        .mode(mode).time(data.getTime()).build());
  }
}
